//! 🔀️ Variant selection retains actual original discriminators and bounded schema comparisons.
use crate::{NativeDecodeControl,OriginalReceivingPrimary,RetainedWorkOutcome,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,retained_clone::{RetainedCloneBinding,RetainedCloneRef,retained_clone_grant_admits},owned::{NativeRecordMatcher,NativeRecordSchema,NativeSchemaLeaf,NativeSchemaKeySource,NativeFieldMatch,tree::{NativeValueSource,NativeTreeKind,fixed,receipt,invalid,nested,child_grant}}};
#[derive(Clone,Copy)]pub struct NativeVariantSpec{pub all:fn(usize)->Option<NativeRecordSchema>,pub units:fn(usize)->Option<NativeRecordSchema>,pub data:fn(usize)->Option<NativeRecordSchema>,pub count:usize,pub tag:Option<fn(usize)->Option<NativeRecordSchema>>}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct NativeVariantSelection{pub index:usize,pub direct:bool}
pub struct NativeVariantSelector<I:NativeValueSource+?Sized>{binding:Option<RetainedCloneBinding>,matcher:Option<NativeRecordMatcher<I>>,spec:NativeVariantSpec,selection:Option<NativeVariantSelection>,tag:Option<usize>,scan:usize,phase:u8,direct:bool,closing:bool,failed:bool}
impl<I:NativeValueSource+?Sized>NativeVariantSelector<I>{
 pub fn new(spec:NativeVariantSpec)->Self{Self{binding:None,matcher:None,spec,selection:None,tag:None,scan:0,phase:0,direct:false,closing:false,failed:false}}
 pub fn result(&self)->Option<NativeVariantSelection>{self.selection}
 pub fn validate_input(&self,input:RetainedCloneRef<'_,I>)->Result<(),ValueError>{input.check_binding(&self.binding)?;Ok(())}
 pub fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}if self.selection.is_some()||self.failed{return Ok(Default::default())}if !input.check_binding(&self.binding)?{return Ok(fixed(input.binding_copy_bytes()))}if let Some(matcher)=self.matcher.as_ref(){if self.phase==3{return if matcher.terminal_is_empty(){Ok(fixed(0))}else{nested(matcher.close_demands(body)?,0)}}if matcher.result().is_none(){return nested(matcher.demands(input,body)?,0)}}Ok(fixed(0))}
 pub fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{if self.failed{return RetainedWorkOutcome{result:Err(invalid().into()),work:0}}if self.selection.is_some(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let mut work=0;let result:Result<RetainedCloneStep,OriginalReceivingPrimary>=(||{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;if self.binding.is_none(){let turn=input.bind(&mut self.binding,g);let turn=control.receive_retained_work(g,RetainedWorkOutcome{result:turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())),work:turn.work});work=turn.work;return turn.result.map_err(Into::into)}
  if let Some(matcher)=self.matcher.as_mut(){if self.phase==3&&!matcher.terminal_is_empty(){let turn=matcher.close_step(child_grant(g,0));work=turn.work;let turn=control.receive_retained_work(g,turn);return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if self.phase!=3&&matcher.result().is_none(){let turn=matcher.advance(input,control,body,child_grant(g,0));work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}}
  work=1;match self.phase{
   0=>self.phase=1,
   1=>{if input.get().variant_tag().is_some(){self.direct=true;self.matcher=Some(NativeRecordMatcher::new(self.spec.all,self.spec.count,NativeSchemaKeySource::VariantTag));self.phase=4;}else if self.spec.tag.is_some(){self.phase=2;}else if input.get().tree_kind()==Some(NativeTreeKind::Text){self.matcher=Some(NativeRecordMatcher::new(self.spec.units,self.spec.count,NativeSchemaKeySource::Text));self.phase=4;}else if input.get().tree_kind().is_none(){self.matcher=Some(NativeRecordMatcher::new(self.spec.units,self.spec.count,NativeSchemaKeySource::EnumOrdinal));self.phase=4;}else{if input.get().record_len()?!=1{return Err(invalid().into())}self.matcher=Some(NativeRecordMatcher::new(self.spec.data,self.spec.count,NativeSchemaKeySource::RecordName(0)));self.phase=4;}},
   2=>{if let Some(matcher)=self.matcher.as_mut(){match matcher.result().ok_or_else(invalid)?{NativeFieldMatch::Field(_)=>{if self.tag.is_some(){self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())}self.tag=Some(self.scan);},NativeFieldMatch::Ambiguous=>{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())},NativeFieldMatch::Missing=>{}}matcher.begin_close();self.phase=3;}else{let count=input.get().record_len()?;if self.scan==count{let tag=self.tag.ok_or_else(invalid)?;self.matcher=Some(NativeRecordMatcher::new(self.spec.all,self.spec.count,NativeSchemaKeySource::RecordText(tag)));self.phase=4;}else{self.matcher=Some(NativeRecordMatcher::new(self.spec.tag.ok_or_else(invalid)?,1,NativeSchemaKeySource::Record(self.scan)));}}},
   3=>{self.matcher=None;self.scan+=1;self.phase=2;},
   4=>{let NativeFieldMatch::Field(index)=self.matcher.as_ref().ok_or_else(invalid)?.result().ok_or_else(invalid)?else{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())};if index>=self.spec.count{self.failed=true;return Err(invalid().with_retained_progress(receipt(fixed(0))).into())}self.selection=Some(NativeVariantSelection{index,direct:self.direct});self.phase=5;},
   _=>return Err(invalid().into()),
  }Ok(if self.selection.is_some(){RetainedCloneStep::Complete(receipt(fixed(0)))}else{RetainedCloneStep::Progress(receipt(fixed(0)))})})();let result=result;RetainedWorkOutcome{result,work}}
 pub fn begin_settlement(&mut self){if let Some(matcher)=self.matcher.as_mut(){matcher.begin_close();}}
 pub fn settled(&self)->bool{self.matcher.is_none()}
 pub fn settlement_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(matcher)=self.matcher.as_ref(){if matcher.terminal_is_empty(){Ok(fixed(0))}else{nested(matcher.close_demands(body)?,0)}}else{Ok(Default::default())}}
 pub fn settle_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{if self.matcher.is_none(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let d=match self.settlement_demand(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}let matcher=match self.matcher.as_mut(){Some(v)=>v,None=>return RetainedWorkOutcome{result:Err(ValueError::invariant("matcher absent").into()),work:0}};if matcher.terminal_is_empty(){self.matcher=None;return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(receipt(fixed(0)))),work:1}}matcher.close_step(child_grant(g,0))}
 pub fn begin_close(&mut self){self.closing=true;if let Some(matcher)=self.matcher.as_mut(){matcher.begin_close();}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.matcher.is_some(){return self.settlement_demand(body)}if self.binding.is_some(){return RetainedCloneBinding::close_demand(&self.binding,body)}if self.phase!=6{return Ok(fixed(0))}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let mut work=0;let result=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.matcher.is_some(){let turn=self.settle_step(g);work=turn.work;return turn.result}if self.binding.is_some(){let turn=RetainedCloneBinding::close_one(&mut self.binding,g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}self.selection=None;self.tag=None;self.failed=false;self.phase=6;work=1;Ok(RetainedCloneStep::Complete(receipt(fixed(0))))})();RetainedWorkOutcome{result,work}}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.matcher.is_none()&&(self.phase==6||self.phase==0)}
}
impl<I:NativeValueSource+?Sized>Drop for NativeVariantSelector<I>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native variant selector requires funded closure")}}

#[path="🔢️unit/🦀️.rs"]mod unit;
pub use unit::{NativeUnitVariants,NativeUnitEnumReceiver};

use crate::owned::{NativeReceive,NativeReceiver,tree::{NativeReceiveSlot}};
fn result_variant(index:usize)->Option<NativeRecordSchema>{["Ok","Err"].get(index).map(|name|NativeRecordSchema::Leaf(NativeSchemaLeaf{name,ordinal:index as u32}))}
fn result_unit(index:usize)->Option<NativeRecordSchema>{(index<2).then_some(NativeRecordSchema::Skip)}
pub struct NativeResultReceiver<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,E:NativeReceive<dyn NativeValueSource>>{selector:NativeVariantSelector<I>,ok:NativeReceiveSlot<dyn NativeValueSource,T>,err:NativeReceiveSlot<dyn NativeValueSource,E>,closing:bool,taken:bool}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,E:NativeReceive<dyn NativeValueSource>> NativeReceive<I> for Result<T,E>{type Receiver=NativeResultReceiver<I,T,E>;fn receiver()->Self::Receiver{NativeResultReceiver{selector:NativeVariantSelector::new(NativeVariantSpec{all:result_variant,units:result_unit,data:result_variant,count:2,tag:None}),ok:Default::default(),err:Default::default(),closing:false,taken:false}}}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,E:NativeReceive<dyn NativeValueSource>> NativeResultReceiver<I,T,E>{
 fn payload<'a>(&self,input:RetainedCloneRef<'a,I>)->Result<RetainedCloneRef<'a,dyn NativeValueSource>,ValueError>{let selected=self.selector.result().ok_or_else(invalid)?;if selected.direct{input.get().variant_payload()?;}else{input.get().record_child(0)?;}Ok(input.project(selected.index,move|value|if selected.direct{value.variant_payload().expect("bound Result variant payload")}else{value.record_child(0).expect("bound Result record payload")}))}
 fn child_ready(&self)->bool{self.selector.result().is_some_and(|selected|if selected.index==0{self.ok.ready()}else{self.err.ready()})}
}
impl<I:NativeValueSource+?Sized,T:NativeReceive<dyn NativeValueSource>,E:NativeReceive<dyn NativeValueSource>> NativeReceiver<I,Result<T,E>> for NativeResultReceiver<I,T,E>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.taken{return Err(invalid())}self.selector.validate_input(input)?;let Some(selected)=self.selector.result()else{return self.selector.demands(input,body)};if self.child_ready(){return self.selector.settlement_demand(body)}let payload=self.payload(input)?;nested(if selected.index==0{self.ok.demands(payload,body)?}else{self.err.demands(payload,body)?},0)}
 fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{let mut work=0;let result:Result<RetainedCloneStep,OriginalReceivingPrimary>=(||{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;let turn=if let Some(selected)=self.selector.result(){if self.child_ready(){let turn=control.receive_retained_work(g,self.selector.settle_step(g));RetainedWorkOutcome{result:turn.result.map_err(Into::into),work:turn.work}}else{let payload=self.payload(input)?;if selected.index==0{self.ok.advance(payload,control,body,child_grant(g,0))}else{self.err.advance(payload,control,body,child_grant(g,0))}}}else{let turn=self.selector.advance(input,control,body,g);if self.selector.result().is_some(){self.selector.begin_settlement()}turn};work=turn.work;turn.result.map(|step|if self.output_ready(){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})})();RetainedWorkOutcome{result,work}}
 fn output_ready(&self)->bool{!self.closing&&!self.taken&&self.child_ready()&&self.selector.settled()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(RetirementDemand{depth:2,..fixed(std::mem::size_of::<Result<T,E>>())})}
 fn take(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<(Result<T,E>,RetainedCloneProgress)>>{let mut work=0;let result=(||{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None)}let selected=self.selector.result().ok_or_else(invalid)?;let turn=if selected.index==0{let turn=self.ok.take(child_grant(g,d.copy_bytes));RetainedWorkOutcome{result:turn.result.map(|v|v.map(|(v,p)|(Ok(v),p))),work:turn.work}}else{let turn=self.err.take(child_grant(g,d.copy_bytes));RetainedWorkOutcome{result:turn.result.map(|v|v.map(|(v,p)|(Err(v),p))),work:turn.work}};work=turn.work;let Some((value,p))=turn.result?else{return Ok(None)};self.taken=true;Ok(Some((value,RetainedCloneProgress{copied_bytes:p.copied_bytes+d.copy_bytes,..p})))})();RetainedWorkOutcome{result,work}}
 fn begin_close(&mut self){self.closing=true;self.ok.begin_close();self.err.begin_close();self.selector.begin_close()}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if !self.ok.terminal_is_empty(){return nested(self.ok.close_demands(body)?,0)}if !self.err.terminal_is_empty(){return nested(self.err.close_demands(body)?,0)}self.selector.close_demands(body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if !self.ok.terminal_is_empty(){self.ok.close_step(child_grant(g,0))}else if !self.err.terminal_is_empty(){self.err.close_step(child_grant(g,0))}else{self.selector.close_step(g)}}
 fn terminal_is_empty(&self)->bool{self.ok.terminal_is_empty()&&self.err.terminal_is_empty()&&self.selector.terminal_is_empty()}
}
